INSERT INTO `library_items` VALUES ('0b1d4d1d-db91-47b3-82e5-c41de9f037d3','4d8e5d96-73c0-4502-ae66-6142ae91a775','3d841e1d-9e9a-42c2-98ce-93463d4bfa04','METHODICAL','ЕББҚ · Сөйлеу тілі және коммуникация (АСБ / РАС) | Жеке бейімдеу дәрежесі','Сөйлеу тілі бұзылыстары және аутизм спектрі (АСБ / РАС) ерекшеліктері','Нарушения речи и расстройства аутистического спектра (РАС)','Коммуникативтік және сенсорлық ерекшеліктер: сабақ құрылымының тұрақты әрі алдын ала түсінікті болуы, тапсырманы қысқа әрі нақты алгоритммен беру. Көпшілік алдында ауызша жауап беруді талап етпеу — жеке жазбаша, карточкалық немесе компьютерлік форматта бағалау. Шу мен артық сенсорлық жүктемені азайту.','Особенности восприятия и коммуникации: чёткая и предсказуемая структура занятия, однозначные пошаговые инструкции без метафор. Замена публичных устных выступлений у доски на индивидуальную сдачу, письменный ответ или защиту проекта в спокойной обстановке. Снижение сенсорных перегрузок.','2026-11-19 10:00:00.000',1,'2026-11-24 20:28:27.703','2026-11-24 20:28:27.703'),('18730b1f-840b-44e0-a994-523b2b0dce4a','4d8e5d96-73c0-4502-ae66-6142ae91a775','3d841e1d-9e9a-42c2-98ce-93463d4bfa04','TEACHER_GUIDE','Әдістемелік ұсыным','Визуалды тіректер мен баламалы бағалауды қолдану','Использование визуальных опор и альтернативного оценивания','Ірілендірілген шартты белгілер карточкалары, алгоритмдік сызбалар және оқу мақсатына сәйкес баламалы бағалау тәсілдері.','Укрупнённые карточки условных обозначений, алгоритмические схемы и методы альтернативного оценивания по учебным целям.','2026-11-19 10:00:00.000',1,'2026-11-20 22:33:58.105','2026-11-20 22:33:58.105'),('2d91bb42-ed02-48f4-b24d-503f6e6a98a8','4d8e5d96-73c0-4502-ae66-6142ae91a775','3d841e1d-9e9a-42c2-98ce-93463d4bfa04','METHODICAL','ЕББҚ · Тірек-қимыл аппараты (ТҚА / НОДА) | Жеңіл, орташа, ауыр дәреже','Тірек-қимыл аппараты (ТҚА) бұзылған студенттермен жұмыс','Особенности студентов с нарушениями опорно-двигательного аппарата (НОДА)','Жеңіл дәреже: стандартты жұмыс орнын бейімдеу, ұзақ жазудан қолдың шаршауын ескеру. Орташа және ауыр дәреже (соның ішінде БЦП / ДЦП, ұсақ моторика бұзылысы): арнайы эргономикалық үстел және арбаға қолжетімді өту жолы, зертханалық жұмыста виртуалды симуляторлар мен ірі детальдарды қолдану, жазбаша конспектілерді электронды форматта беру.','Лёгкая степень: снижение объёма рукописного текста, предоставление готовых опорных конспектов. Средняя и тяжёлая степень (включая ДЦП и нарушения мелкой моторики): свободный подъезд к рабочему стенду, использование компьютерных симуляторов при сложностях с пайкой/мелким монтажом, дополнительное время на выполнение практических операций.','2026-11-19 10:00:00.000',1,'2026-11-24 20:28:27.022','2026-11-24 20:28:27.022'),('73b5faff-176a-4cb6-bb03-5138be528bbd','4d8e5d96-73c0-4502-ae66-6142ae91a775','3d841e1d-9e9a-42c2-98ce-93463d4bfa04','METHODICAL','Чек-парақ','Бейімделген сабақ пен баламалы бағалау чек-парағы','Чек-лист адаптированного занятия и альтернативного оценивания','Оқытушы мен дефектологке арналған сабақ алдындағы дайындық және оқу мақсатының орындалуын тексеру чек-парағы.','Чек-лист подготовки адаптированного занятия и проверки достижения индивидуальной учебной цели.','2026-11-19 10:00:00.000',1,'2026-11-20 22:33:58.328','2026-11-20 22:33:58.328'),('84f91a0a-26d0-4c77-84d7-1a9065a51f95','4d8e5d96-73c0-4502-ae66-6142ae91a775','3d841e1d-9e9a-42c2-98ce-93463d4bfa04','NORMATIVE','ҚР Бұйрықтары мен қағидалары','Инклюзивті білім беруді ұйымдастыру қағидалары','Правила организации инклюзивного образования в ТиПО','Техникалық және кәсіптік білім беру ұйымдарында ерекше білім беру қажеттіліктері бар студенттерді психологиялық-педагогикалық сүйемелдеу тәртібі мен нормативтік талаптар.','Нормативные требования и порядок психолого-педагогического сопровождения студентов с особыми образовательными потребностями в колледже.','2026-11-19 10:00:00.000',1,'2026-11-20 22:33:57.361','2026-11-20 22:33:57.361'),('af51a728-1281-4705-ad59-42261b99a540','4d8e5d96-73c0-4502-ae66-6142ae91a775','3d841e1d-9e9a-42c2-98ce-93463d4bfa04','METHODICAL','ЕББҚ · Танымдық процестер ерекшеліктері (ПДТ / ЗПР) | І–ІІ дәреже','Танымдық процестер мен зейін ерекшеліктері (ПДТ / ЗПР)','Особенности познавательных процессов и внимания (ЗПР)','Жұмыс қарқынының баяулығы мен зейіннің тез шаршауы: көлемді теориялық материалды шағын блоктарға (10–15 минут) бөлу, әр блоктан кейін практикалық бекіту. Тірек схемалар, формулалар мен шартты белгілер кестесін емтихан мен сабақ үстінде пайдалануға рұқсат беру.','Особенности темпа деятельности и концентрации внимания: дробление сложных заданий на 3–4 коротких шага с промежуточной проверкой. Разрешение использовать опорные схемы, справочные карточки условных обозначений и шаблоны решений на практических занятиях и зачётах.','2026-11-19 10:00:00.000',1,'2026-11-24 20:28:28.071','2026-11-24 20:28:28.071'),('b271fa83-2e24-44b2-8ae4-4eaccb0706a8','4d8e5d96-73c0-4502-ae66-6142ae91a775','3d841e1d-9e9a-42c2-98ce-93463d4bfa04','NORMATIVE','Колледждің ішкі ережелері','Психологиялық-педагогикалық консилиум туралы ереже','Положение о психолого-педагогическом консилиуме колледжа','Мамандар консилиумының жұмыс регламенті, рөлдік жауапкершілік матрицасы және жеке деректерді қорғау талаптары.','Регламент работы консилиума специалистов, матрица ролевой ответственности и требования по защите персональных данных.','2026-11-19 10:00:00.000',1,'2026-11-20 22:33:57.640','2026-11-20 22:33:57.640'),('d6e43be3-41a4-45f8-af63-83a82075b9e8','4d8e5d96-73c0-4502-ae66-6142ae91a775','3d841e1d-9e9a-42c2-98ce-93463d4bfa04','METHODICAL','ЕББҚ · Есту қабілеті бұзылған (Нашар еститіндер) | І, ІІ, ІІІ, ІV дәреже','Есту қабілеті бұзылған студенттерді оқыту ерекшеліктері (І–ІV дәреже)','Особенности обучения слабослышащих студентов (I–IV степень тугоухости)','І–ІІ дәреже (жеңіл және орташа): оқытушыға бетпе-бет (1–2 парта) отырғызу, анық артикуляция, барлық ауызша терминдерді тақтада немесе слайдта жазбаша қайталау. ІІІ–ІV дәреже (орташа-ауыр және ауыр): бейнематериалдарды міндетті субтитрмен беру, практикалық жұмыстарды толық иллюстрацияланған қадамдық нұсқаулықпен (чек-парақпен) ұсыну, ауызша емтиханды жазбаша/тест форматына ауыстыру.','I–II степень (лёгкая и умеренная тугоухость): посадка за 1–2 парту лицом к преподавателю для чтения с губ, чёткая артикуляция, дублирование новых терминов на слайде. III–IV степень (среднетяжёлая и тяжёлая): субтитры ко всем видеоматериалам, письменные пошаговые алгоритмы к практическим и лабораторным работам, замена устных ответов письменными или демонстрацией навыка.','2026-11-19 10:00:00.000',1,'2026-11-24 20:28:26.758','2026-11-24 20:28:26.758'),('dc96e4b9-0ac7-4bd3-8abf-a0ea1b246b6c','4d8e5d96-73c0-4502-ae66-6142ae91a775','3d841e1d-9e9a-42c2-98ce-93463d4bfa04','METHODICAL','ЕББҚ · Көру қабілеті бұзылған (Нашар көретіндер) | І, ІІ, ІІІ дәреже','Көру қабілеті бұзылған студенттердің ерекшеліктері (І, ІІ, ІІІ дәреже)','Особенности обучения слабовидящих студентов по степеням (I, II, III степень)','І дәреже (жеңіл): алдыңғы парта (1–2 қатар), шрифт 14–16 pt, қосымша жарық (500 лк). ІІ дәреже (орташа): шрифт 18–20 pt, жоғары контрастты сызбалар (қара/сары, ақ/қара), үлкейткіш лупа және экран дикторы. ІІІ дәреже (ауыр): аудио-дәрістер, Брайль немесе тактильді-бедерлі электр сұлбалары, жазбаша жұмыс уақытын 1,5 есе ұзарту, әр 20 минут сайын көзге демалыс беру.','I степень (лёгкая): посадка на 1–2 ряду у окна, шрифт 14–16 pt, хорошее освещение. II степень (средняя): шрифт 18–20 pt без засечек, высококонтрастные схемы и чертежи, экранная лупа. III степень (тяжёлая): аудиосопровождение лекций, тактильно-рельефные схемы, увеличение времени на лабораторные и контрольные работы в 1,5 раза, зрительная гимнастика каждые 20 минут.','2026-11-19 10:00:00.000',1,'2026-11-24 20:28:26.462','2026-11-24 20:28:26.462'),('dc9a7437-8847-4b25-9f74-c43ae10db4c2','4d8e5d96-73c0-4502-ae66-6142ae91a775','3d841e1d-9e9a-42c2-98ce-93463d4bfa04','TEACHER_GUIDE','Сабақты бейімдеу','Практикалық тапсырманы шағын кезеңдерге бөлу нұсқаулығы','Инструкция по делению практического задания на этапы','Электртехника және арнайы пәндерде күрделі практикалық жұмысты 3-4 нақты қадамға бөліп ұсыну және әр қадамның орындалуын тексеру әдістемесі.','Методика пошагового представления практических работ по электротехнике и спецдисциплинам с контролем каждого этапа.','2026-11-19 10:00:00.000',1,'2026-11-20 22:33:57.878','2026-11-20 22:33:57.878'),('ed01ad4e-7599-449c-9ae1-525f7422e070','4d8e5d96-73c0-4502-ae66-6142ae91a775','3d841e1d-9e9a-42c2-98ce-93463d4bfa04','METHODICAL','Оқу материалы','Электр сұлбаларының шартты белгілері (бейімделген карточкалар үлгісі)','Условные обозначения электрических схем (шаблон адаптированных карточек)','Электртехника сабағында қолдануға арналған ірілендірілген шартты белгілер мен кезеңдік тапсырма үлгісі.','Шаблон укрупнённых карточек условных обозначений и пошагового задания для занятий по электротехнике.','2026-11-19 10:00:00.000',1,'2026-11-20 22:33:58.566','2026-11-20 22:33:58.566');
